Definition req_frames (m : mem) (sp : word) (ra s0 s1 s2 s3 s4 : word) (w0 w1 w2 w3 w4 : Z) (rar : Z) : Prop :=
  rw_cells usegs m (bv_unsigned sp + -16) [C8 (wz 0); C8 ra]
  /\ rw_cells usegs m (bv_unsigned sp + -64) [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 (wz THUNK_RET)]
  /\ rw_cells usegs m (bv_unsigned sp + -112) [C8 (wz w0); C8 (wz w1); C8 (wz w2); C8 (wz w3); C8 (wz w4); C8 (wz rar)].

Definition req_pure (sp : word) (P MP TP lo : Z) (mbs tbs : list byte) : Prop :=
  1 <= Z.of_nat (length mbs) < 2^26 /\ 1 <= Z.of_nat (length tbs) < 2^26
  /\ MP + Z.of_nat (length mbs) <= hceil /\ TP + Z.of_nat (length tbs) <= hceil
  /\ bv_unsigned sp <= P /\ P + 256 <= 2^64 /\ hceil <= lo /\ lo + 192 <= bv_unsigned sp.

(* [comment removed for export] *)
Definition req_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P verb MP TP ver lo : Z) (mbs tbs : list byte) (h : hdrv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m1,
    ms' = MS (mkR (wz RT_RET1) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz (P + 144)) (wz (Z.of_nat (length mbs)))
                  (wz (Z.of_nat (length tbs) + 1)) a1 a2 a3 a4 a5 a6 a7
                  (wz (Z.of_nat (length tbs))) (wz (P + 80)) (wz verb) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz ROPNEW) fc None m1 (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (P + O_PR_USED, P + O_PR_USED + 1)]%Z m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1
    /\ stk usegs m1 lo (bv_unsigned sp + -112)
    /\ req_frames m1 sp ra s0 s1 s2 s3 s4 TP (Z.of_nat (length tbs)) MP (Z.of_nat (length mbs)) ver WK_RET_RT
    /\ rw_cells usegs m1 (P + O_PR_USED) [C1 (b8 1)]
    /\ rw_cells usegs m1 (P + O_PR_HDR) (HdrCells h)
    /\ bytes_at usegs m1 MP mbs /\ bytes_at usegs m1 TP tbs.

Definition req_seg1_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P verb MP TP ver lo : Z) (mbs tbs : list byte) (h : hdrv),
  rw_cells usegs m (P + O_PR_USED) [C1 (b8 0)] ->
  rw_cells usegs m (P + O_PR_HDR) (HdrCells h) -> hdr_empty h ->
  bytes_at usegs m MP mbs -> bytes_at usegs m TP tbs ->
  stk usegs m lo (bv_unsigned sp) ->
  req_pure sp P MP TP lo mbs tbs -> 0 <= verb < 2^32 -> (ver = 10 \/ ver = 11) ->
  mem_inv usegs m ->
  evt usegs (req_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P verb MP TP ver lo mbs tbs h m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz verb) (wz MP) (wz (Z.of_nat (length mbs))) (wz TP) (wz (Z.of_nat (length tbs)))
              (wz ver) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ON_REQUEST_IMPL) fc None m (seg_rom usegs)).
