(* [comment removed for export] *)
Definition req_tail_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (h : hdrv) (ver : Z) (m1 : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m2,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m2 (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (P + O_PR_HDR, P + O_PR_HDR + 40)]%Z m1 m2 /\ wmono usegs m1 m2 /\ mem_inv usegs m2
    /\ stk usegs m2 lo (bv_unsigned sp)
    /\ rw_cells usegs m2 (P + O_PR_HDR) (HdrCells (mkHV (hv_mp h) (hv_ml h) (hv_tp h) (hv_tl h) ver (hv_vb h))).

Definition req_tail_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s4x s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (P lo ver : Z) (h : hdrv),
  rw_cells usegs m1 (bv_unsigned sp + -16) [C8 (wz 0); C8 ra] ->
  rw_cells usegs m1 (bv_unsigned sp + -64) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 (wz THUNK_RET)] ->
  rw_cells usegs m1 (P + O_PR_HDR) (HdrCells h) -> 0 <= hv_ver h < 2^32 ->
  stk usegs m1 lo (bv_unsigned sp + -64) ->
  bv_unsigned sp <= P -> P + 256 <= 2^64 -> 0 <= lo -> lo + 80 <= bv_unsigned sp -> (ver = 10 \/ ver = 11) ->
  mem_inv usegs m1 ->
  evt usegs (req_tail_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P lo h ver m1)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz ver) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x (wz (P + 80)) s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 WK_RET_RS) fc None m1 (seg_rom usegs)).

